// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient) public {
        RevertingRecipient reverter = new RevertingRecipient();
        address recipientAddress = address(reverter);
        vm.deal(address(c), 1 ether);
        bool success;
        try c.withdrawAll(recipientAddress) { success = true; } catch { success = false; }
        assertTrue(!success ? address(c).balance > 0 : address(c).balance == 0);
    }
}

contract RevertingRecipient {
    fallback() external payable { revert(); }
}
